const D = { energy:.6, scale:1, density:.5, speed:1, wind:.7, alpha:.85, hue:42, x:.5, y:.82, style:'newsprint', act:'scud', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>Math.max(a,Math.min(b,v));
const lrp=(a,b,t)=>a+(b-a)*t;
const md=(a,n)=>((a%n)+n)%n;
const frc=v=>v-Math.floor(v);
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
const rgbs=(h,s,v,a)=>{const H2=md(h,360)/60,S2=clp(s,0,1),V2=clp(v,0,1);const c=V2*S2,x=c*(1-Math.abs(H2%2-1)),m=V2-c;let r=0,g=0,b=0;
  if(H2<1){r=c;g=x;}else if(H2<2){r=x;g=c;}else if(H2<3){g=c;b=x;}else if(H2<4){g=x;b=c;}else if(H2<5){r=x;b=c;}else{r=c;b=x;}
  return 'rgba('+(((r+m)*255)|0)+','+(((g+m)*255)|0)+','+(((b+m)*255)|0)+','+clp(a,0,1).toFixed(3)+')';};

const W=width, Hh=height, u=Math.min(W,Hh);
const H=md(P.hue,360);
const st=P.style, act=P.act||'scud';
const isPly=st==='polythene', isBkl=st==='backlit', isChr=st==='chronograph';
const en=clp(P.energy,0,1), dn=clp(P.density,0,1), al=clp(P.alpha,0,1);
const sc=clp(P.scale,0.4,2.2), sp=clp(P.speed,0.1,4);
const wd=clp(P.wind,-1,1), sgn=wd<0?-1:1, wm=Math.abs(wd)*0.85+0.15;
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const MAXS=16, MAXC=90;
if(S.seedUsed!==P.seed||!S.sh){
  S.seedUsed=P.seed;
  S.sh=[];
  for(let i=0;i<MAXS;i++){
    const nv=8;
    const rr=[];
    for(let j=0;j<nv;j++) rr.push(0.80+fr(i*97+j*17+5)*0.42);
    S.sh.push({
      d: fr(i*3+1),                                  // depth: sets size, speed, alpha
      x0: fr(i*5+2), y0: fr(i*7+3),
      yaw0: fr(i*11+4)*6.2832, p0: fr(i*13+5)*6.2832,
      yr: (0.28+fr(i*17+6)*0.62)*(fr(i*19+7)>0.5?1:-1),   // tumble rates, all incommensurate
      pr: (0.41+fr(i*23+8)*0.93)*(fr(i*29+9)>0.5?1:-1),
      wr: 0.19+fr(i*31+10)*0.44,
      br: 1.7+fr(i*37+11)*2.9,                        // flap (Strouhal-ish, fast)
      lr: 0.13+fr(i*41+12)*0.29,
      lift: 0.25+fr(i*43+13)*0.75,
      ph: fr(i*47+14)*6.2832,
      tone: 0.62+fr(i*53+15)*0.38,
      cols: 2+Math.floor(fr(i*59+16)*4),
      nv: nv, rr: rr
    });
  }
  S.cf=[];
  for(let i=0;i<MAXC;i++) S.cf.push({
    d: fr(i*61+21), x0: fr(i*67+22), y0: fr(i*71+23),
    r: 0.004+Math.pow(fr(i*73+24),2)*0.020,
    yr: (0.9+fr(i*79+25)*3.1)*(fr(i*83+26)>0.5?1:-1),
    lr: 0.21+fr(i*89+27)*0.71, lift: 0.15+fr(i*101+28)*0.6, ph: fr(i*103+29)*6.2832
  });
}
const t=K.t*sp;

// ---- gust programme: real-time envelopes, incommensurate, never beat-locked ----
const base=0.52+0.26*Math.sin(t*0.071+0.6)+0.14*Math.sin(t*0.163+2.3)+0.08*Math.sin(t*0.317);
let gust=base, vort=0, vx0=0.5, vy0=0.5;
if(act==='gust'){ gust=0.34+1.15*Math.pow(clp(0.5+0.5*Math.sin(t*0.053+1.1),0,1),2.6)+0.16*Math.sin(t*0.29); }
else if(act==='vortex'){
  gust=0.42+0.4*base;
  vort=0.55+0.45*Math.sin(t*0.037+0.8);
  vx0=0.5+0.34*Math.sin(t*0.043)+0.12*Math.sin(t*0.113+1.9);
  vy0=clp(P.y,-0.2,1.2)-0.28+0.10*Math.sin(t*0.067+2.2);
}
const arc=0.72+0.55*K.intensity;
const G=gust*arc*(0.42+0.85*en)*(1+A.bass*0.25);
const nS=Math.max(2,Math.round(lrp(4,MAXS,dn)));
const nC=Math.round(lrp(12,MAXC,dn));
const gy=clp(P.y,-0.2,1.2), lxf=clp(P.x,-0.2,1.2);

// ---- the gust veil: broad grit sweeping with the front, an accent under the sheets ----
blendMode(ADD);
{
  const gp=frc(t*0.061*wm+0.2)*1.5-0.25;
  const gxp=(sgn>0?gp:1-gp)*W, gw=W*(0.20+0.34*clp(G,0,1.4));
  const gc=rgbs(H-4, isBkl?0.10:0.34, 1, 1);
  const ga=clp(0.135*al*(0.3+0.85*en)*(0.4+0.7*clp(G,0,1.4)),0,0.26);
  const gr=drawingContext.createLinearGradient(gxp-gw,0,gxp+gw,0);
  gr.addColorStop(0,gc.replace(/[\d.]+\)$/,'0)'));
  gr.addColorStop(0.5,gc.replace(/[\d.]+\)$/,ga.toFixed(3)+')'));
  gr.addColorStop(1,gc.replace(/[\d.]+\)$/,'0)'));
  drawingContext.fillStyle=gr;
  drawingContext.fillRect(0,0,W,Hh);
  // a low band of streaming grit along the ground line
  const bh2=Hh*0.30;
  const br2=drawingContext.createLinearGradient(0,gy*Hh-bh2,0,gy*Hh+bh2*0.4);
  const ba=clp(0.105*al*(0.3+0.8*en)*(0.5+0.6*clp(G,0,1.4)),0,0.21);
  br2.addColorStop(0,gc.replace(/[\d.]+\)$/,'0)'));
  br2.addColorStop(0.75,gc.replace(/[\d.]+\)$/,ba.toFixed(3)+')'));
  br2.addColorStop(1,gc.replace(/[\d.]+\)$/,(ba*0.4).toFixed(3)+')'));
  drawingContext.fillStyle=br2;
  drawingContext.fillRect(0,Math.max(0,gy*Hh-bh2),W,bh2*1.4);
}
blendMode(BLEND);

const place=(o,spdK,liftK)=>{
  const d=o.d;
  let px, py;
  if(act==='vortex'&&vort>0.05){
    const orb=0.9+d*0.6, om=(0.09+d*0.16)*sp*(0.5+wm);
    const a2=o.ph+t*om*sgn;
    const rr=(0.10+0.30*frc(o.x0+t*0.013))*orb*vort;
    px=(vx0+Math.cos(a2)*rr*(W>Hh?1:0.7))*W;
    py=(vy0+Math.sin(a2)*rr*0.62)*Hh;
  } else {
    const v=lrp(0.030,0.115,d)*wm*spdK*sgn;
    px=(frc(o.x0+v*t)*1.3-0.15)*W;
    const yb=gy-lrp(0.02,0.15,d);
    const lift=G*o.lift*liftK*(0.5+0.5*Math.sin(t*o.lr+o.ph))+0.06*Math.sin(t*o.lr*2.7+o.ph);
    py=(yb-lift*0.62+ (o.y0-0.5)*0.10)*Hh;
  }
  return [px,py,d];
};

// ---- torn scraps: fine detail riding on the sheets, never carrying the read ----
blendMode(isChr?BLEND:ADD);
noStroke();
for(let i=0;i<nC;i++){
  const c=S.cf[i];
  const pp=place(c,1.25,1.15);
  if(pp[0]<-30||pp[0]>W+30) continue;
  const fxq=Math.abs(Math.cos(c.ph+t*c.yr))*0.85+0.15;
  const rad=c.r*u*sc*(0.5+pp[2]);
  const aa=clp((isChr?34:22+58*fxq)*al*lrp(0.45,1,pp[2]),0,72);
  fill(H+lrp(-6,8,fxq), isBkl?6:isPly?5:14, lrp(48,100,fxq), aa);
  push(); translate(pp[0],pp[1]); rotate(c.ph+t*c.yr*0.6); scale(1,clp(fxq,0.12,1));
  rect(-rad,-rad*0.7,rad*2,rad*1.4);
  pop();
}
blendMode(BLEND);

// ---- the sheets: big bodies that cross the whole frame — THIS is the area element ----
for(let i=0;i<nS;i++){
  const s=S.sh[i];
  const pp=place(s,1,1);
  const px=pp[0], py=pp[1], d=pp[2];
  const size=u*lrp(0.075,0.26,d)*sc;
  if(px<-size*2||px>W+size*2||py<-size*2||py>Hh+size*2) continue;
  const pitch=s.p0+t*s.pr*(0.35+wm*0.9)*(0.5+0.8*en);
  const fxq=Math.abs(Math.cos(pitch));                 // foreshortening: edge-on sheets nearly vanish
  const sq=clp(fxq,0.05,1);
  const spin=s.yaw0+t*s.yr*(0.3+wm*0.7)*(0.4+0.8*en);
  const flap=Math.sin(t*s.br*(0.4+0.9*wm)+s.ph);
  // light: face-on to the source catches it, edge-on does not
  const toL=Math.atan2(gy*Hh-0.4*Hh-py, lxf*W-px);
  const face=clp(0.22+0.78*fxq*(0.55+0.45*Math.cos(spin-toL)),0,1);
  const aBase=lrp(0.55,1,d)*al;
  push();
  translate(px,py);
  rotate(spin*0.42+0.35*flap);
  scale(1,sq);
  const hw=size*0.62, hh2=size*0.46;
  let hh3,ss3,vv3,aa3;
  if(isPly){ hh3=H+lrp(150,168,face); ss3=lrp(0.16,0.03,face); vv3=lrp(0.42,1,Math.pow(face,0.6)); aa3=lrp(30,72,face)*aBase; }
  else if(isBkl){ hh3=H+lrp(-8,16,face); ss3=lrp(0.30,0.06,face); vv3=lrp(0.30,1,Math.pow(face,0.5)); aa3=lrp(38,88,face)*aBase; }
  else if(isChr){ hh3=H+178; ss3=0.55; vv3=0.95; aa3=0; }
  else { hh3=H+lrp(-4,6,face); ss3=lrp(0.20,0.05,face)*s.tone; vv3=lrp(0.34,0.99,Math.pow(face,0.72))*s.tone; aa3=lrp(52,94,face)*aBase; }
  if(isChr){
    // Marey motion study: the sheet's recent history as fading outlines + a velocity vector
    noFill();
    for(let k=3;k>=0;k--){
      const kk=k*0.055;
      push(); translate(-sgn*hw*2.1*kk*(0.4+wm), hh2*0.5*kk*flap); rotate(-s.yr*kk*2.2);
      stroke(H+178,52,96,clp((72-k*17)*aBase,0,80)); strokeWeight(Math.max(0.5,u*0.0013*(1-k*0.18)));
      beginShape();
      for(let j=0;j<=s.nv;j++){ const a2=j/s.nv*6.2832; vertex(Math.cos(a2)*hw*s.rr[j%s.nv],Math.sin(a2)*hh2*s.rr[j%s.nv]); }
      endShape(CLOSE);
      pop();
    }
    stroke(H+150,70,100,clp(80*aBase,0,86)); strokeWeight(Math.max(0.8,u*0.0018));
    line(0,0,sgn*hw*1.5*(0.4+wm),-hh2*0.5*flap);
    noStroke();
  } else {
    blendMode(ADD);
    noStroke();
    fill(hh3,ss3*100,vv3*100,clp(aa3,0,94));
    beginShape();
    for(let j=0;j<=s.nv+2;j++){
      const a2=(j%s.nv)/s.nv*6.2832;
      const bow=1+0.16*Math.sin(a2*2+flap*1.7)+0.09*Math.sin(a2*3-t*s.br*0.3);
      curveVertex(Math.cos(a2)*hw*s.rr[j%s.nv]*bow, Math.sin(a2)*hh2*s.rr[j%s.nv]*bow);
    }
    endShape(CLOSE);
