    stroke(hh3,ss3*60,Math.min(100,vv3*128),clp(aa3*0.7,0,72));
    strokeWeight(Math.max(0.5,u*0.0016*sc*(0.4+d)));
    noFill();
    beginShape();
    for(let j=0;j<=4;j++){ const f=j/4; vertex(lrp(-hw*0.9,hw*0.9,f), Math.sin(f*3.1416+flap)*hh2*0.42); }
    endShape();
    noStroke();
    if(isPly){
      // polythene: a hard specular streak that skates across the crinkle
      fill(H+160,3,100,clp(aa3*0.85,0,74));
      push(); rotate(0.5*flap); rect(-hw*0.5,-hh2*(0.08+0.06*fxq),hw*1.0,hh2*0.10); pop();
    } else if(!isBkl){
      // newsprint: column rules and a halftone block, so it reads as a printed page
      stroke(H-6,16,lrp(20,54,face),clp(aa3*0.5,0,44));
